const body = $input.first().json?.body || $input.first().json || {};
const jd_url = body.jd_url || body.jdUrl || '';
const user_id = body.user_id || body.userId || 'demo_user';
const target_role = body.target_role || body.targetRole || 'Software Engineer';
const target_company = body.target_company || body.targetCompany || 'Unknown Company';
const demo_mode = body.demo_mode === true || body.demoMode === true;
const company_intel = body.company_intel || body.companyIntel || null;

if (!jd_url && !demo_mode) {
  throw new Error('Missing required field: jd_url. Provide a job description URL or set demo_mode: true');
}

return [{
  json: {
    jd_url,
    user_id,
    target_role,
    target_company,
    demo_mode,
    company_intel,
    timestamp: new Date().toISOString()
  }
}];

const { jd_url, demo_mode, target_role, target_company } = $input.first().json;

if (demo_mode) {
  return [{
    json: {
      ...$input.first().json,
      jd_raw: `Job Title: Senior ${target_role}
Company: ${target_company}

About the Role:
We are looking for a Senior ${target_role} to join our team. You will work on cutting-edge AI systems, collaborate with cross-functional teams, and drive technical excellence.

Required Skills:
- Python, TypeScript, Node.js
- Machine Learning, LLMs, RAG systems
- AWS, Docker, Kubernetes
- 5+ years of experience

Nice to Have:
- Experience with n8n or workflow automation
- Open source contributions

Compensation: $180,000 - $220,000 + equity`,
      scrape_source: 'demo_mock'
    }
  }];
}

return [{ json: { ...$input.first().json, needs_scrape: true } }];

const prev = $input.first().json;

// If demo mode already set jd_raw, just sanitize and pass through
if (prev.jd_raw) {
  const clean = prev.jd_raw
    .replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g, '')
    .replace(/\t/g, ' ')
    .substring(0, 8000);
  return [{ json: { ...prev, jd_raw: clean } }];
}

// Firecrawl returns { data: { markdown: '...' } } or { markdown: '...' }
const scraped = prev.data?.markdown || prev.markdown || prev.content || '';

if (!scraped || scraped.length < 100) {
  throw new Error('Failed to scrape job description. Check the URL or use demo_mode: true');
}

const clean = scraped
  .replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g, '')
  .replace(/\t/g, ' ')
  .substring(0, 8000);

return [{ json: { ...prev, jd_raw: clean, scrape_source: 'firecrawl' } }];

