const prev = $input.first().json;
let analysis = {};

try {
  const raw = prev.choices?.[0]?.message?.content || prev.content || '{}';
  const cleaned = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  analysis = JSON.parse(cleaned);
} catch(e) {
  analysis = {
    job_title: prev.target_role || 'Software Engineer',
    company_name: prev.target_company || 'Tech Company',
    seniority_level: 'Senior',
    required_skills: ['Python', 'JavaScript', 'AWS', 'Docker', 'SQL'],
    preferred_skills: ['Kubernetes', 'Terraform', 'GraphQL'],
    ats_keywords: ['machine learning', 'API', 'microservices', 'agile', 'CI/CD', 'cloud', 'data pipeline', 'REST', 'TypeScript', 'LLM'],
    responsibilities: ['Design and build scalable systems', 'Collaborate with product teams', 'Mentor junior engineers'],
    compensation_range: '$150,000 - $200,000',
    remote_policy: 'Hybrid',
    industry: 'Technology'
  };
}

return [{ json: { ...prev, jd_analysis: analysis } }];

const prev = $input.first().json;
const jdData = $('Parse JD Analysis').first().json;

// Reads resume from local file via chroma-api, with fallback
const resume_data = prev?.resume_text || `YOUR FULL NAME | your.email@example.com | Your City, State | yoursite.com\n\nSUMMARY\nAdd your professional summary here. Update your resume at storage/master_resume/master_resume.txt\n\nEXPERIENCE\nJob Title -- Company Name, City, State (Start -- End)\n- Achievement 1 with metrics\n- Achievement 2 with metrics\n\nSKILLS\nAdd your skills here...\n\nEDUCATION\nDegree -- University Name (Year)`;

const jd_analysis = jdData?.jd_analysis || prev?.jd_analysis || {};

return [{
  json: {
    ...jdData,
    master_resume: resume_data,
    context_ready: true,
    jd_analysis
  }
}];

